    static let styleWords =
#####"""
# The words kmap itself writes onto the map: labels for objects OSM leaves unnamed,
# and the notes appended to named ones. OSM's own translations cover only names that
# exist — these are the words for everything that has none.
#
# One entry per line: <key>|<english>|<russian>. The rules quote entries by key
# through StyleWords; a build labelled in Cyrillic takes the third column.

# Trail warnings, written along the way itself.
trail.lost|path disappears|тропа теряется
trail.faint|faint path|тропа плохо видна
